package com.matejpcs.netflared;
public final class Platform{private Platform(){}public static String id(){String o=System.getProperty("os.name","").toLowerCase(),a=System.getProperty("os.arch","").toLowerCase();String p=a.contains("aarch64")||a.contains("arm64")?"arm64":a.contains("arm")?"arm":a.contains("86")&&!a.contains("64")?"386":"amd64";return o.contains("win")?"windows-"+p:o.contains("linux")?"linux-"+p:"unsupported-"+p;}public static boolean supported(){return id().startsWith("linux-")||id().startsWith("windows-");}public static String executableName(){return id().startsWith("windows-")?"cloudflared.exe":"cloudflared";}}
